  'Bu bilgiler yalnızca bu telefonda, şifreli olarak saklanır. Acil durumda yakınların ya da sağlık personeli için hızlıca gösterebilirsin.': 'This information is stored only on this phone, encrypted. In an emergency you can quickly show it to your loved ones or healthcare staff.',
  'Bu bilgiler yalnızca uygulamaya girilen kayıtların özetidir. Eksik kayıtlar gerçek günlük toplamları yansıtmayabilir. Sağlık tavsiyesi veya tanı değildir.': 'This is only a summary of the records entered in the app. Missing entries may not reflect real daily totals. It is not health advice or a diagnosis.',
  'Bu bölüm hakkında': 'About this section',
  'Bu bölüm yalnızca sizin girdiğiniz aşı, kontrol ve gelişim notlarını takip eder. Resmî aşı takvimini otomatik oluşturmaz; tıbbi değerlendirme yerine geçmez. Aşı tarihlerini sağlık kuruluşunuzla doğrulayın.': 'This section only tracks the vaccine, check-up and development notes you enter. It does not create the official vaccination schedule automatically and does not replace medical evaluation. Confirm vaccine dates with your health provider.',
  'Bu cihazda kayıtlı oturum': 'Session saved on this device',
  'Bu cihazdaki kayıt sayıları; gerçek yönetici paneli değildir': 'Record counts on this device; not a real admin panel',
  'Bu cihazdaki kayıtlarımı sil': 'Delete my records on this device',
  'Bu doğum tarihinden önceye ait kayıtlar var. Tarihi kontrol edin veya önce o kayıtları düzenleyin.': 'There are records dated before this date of birth. Check the date or edit those records first.',
  'Bu dönemde bebek oturur, emekler, tutunarak kalkar ve ilk anlamlı seslerini çıkarır.': 'In this period babies sit, crawl, pull to stand and make their first meaningful sounds.',
  'Bu dönemde beslenmenin temeli anne sütü veya uygun bebek mamasıdır. Ek gıda, su ve beslenme değişiklikleri için sağlık uzmanınızın önerilerini izleyin.': 'At this stage the basis of nutrition is breast milk or suitable infant formula. Follow your health professional\'s advice on solids, water and feeding changes.',
  'Bu ekran uygulama içi kontrol listesidir; telefon bildirimi göndermez.': 'This screen is an in-app checklist; it does not send phone notifications.',
  'Bu ekran yalnızca bu cihazda tutulan bazı kayıtların sayısını gösterir. Gerçek yönetici yetkilendirmesi, merkezi kullanıcılar, moderasyon, gelir ve analitik verileri henüz mevcut değildir.': 'This screen only shows the count of some records kept on this device. Real admin authorisation, central users, moderation, revenue and analytics data are not available yet.',
  'Bu ekran yalnızca seçilen çocuğun yeni günlük kayıtlarını özetler. Eski ana bebek kayıtları otomatik aktarılmaz. Sağlık istatistikleri tanı amacı taşımaz.': 'This screen only summarises the selected child\'s new journal entries. Older main baby records are not transferred automatically. Health statistics are not for diagnosis.',
  'Bu ekran yalnızca sunucu tarafından doğrulanmış yöneticilere veri gösterir. Kullanıcıların sağlık kayıtları burada görüntülenmez.': 'This screen only shows data to administrators verified by the server. Users\' health records are not shown here.',
