  'Bu kontrol yalnızca çocuk profillerini ve çocuk bazlı günlük kayıtlarını inceler. Verileri silmez, değiştirmez veya otomatik taşımaz. Eski ana bebek kayıtları kapsam dışındadır.': 'This check only reviews child profiles and child-specific journal entries. It does not delete, change or automatically move data. Older main baby records are out of scope.',
  'Bu konuda uygulamada bilgi bulamadım. Soruyu farklı kelimelerle (ör. "uyku", "ek gıda", "aşı") deneyebilir veya sağlık profesyoneline danışabilirsin.': 'I couldn\'t find information on this in the app. Try different words (e.g. "sleep", "solid food", "vaccine") or ask a health professional.',
