  'Gelişimsel hazır oluşa uygun ek gıdaları güvenli kıvamda sunun; anne sütü veya uygun mama devam eder. Yeni besinlerde alerji belirtilerini gözlemleyin. Bal vermeyin.': 'Offer solids suited to developmental readiness in a safe texture; breast milk or suitable formula continues. Watch for allergy signs with new foods. Don\'t give honey.',
