  'Genel': 'General',
  'Genel bilgilendirme amaçlıdır; tanı ve tedavi yerine geçmez. Acil durumda 112, zehirlenmede 114.': 'For general information; it does not replace diagnosis or treatment. In an emergency, call your local emergency number; for poisoning, call your poison control centre.',
