  'Genellikle 20. haftadan sonra görülen, yüksek tansiyon ve organ etkilenmesiyle seyreden bir durumdur.': 'A condition usually seen after week 20, with high blood pressure and effects on organs.',
  'Genellikle enerjinin arttığı, bebek hareketlerinin hissedilmeye başlandığı dönemdir.': 'Usually a time of more energy, when you start to feel your baby move.',
  'Geniş aile önemli bir destek kaynağıdır; ortak kurallar çatışmayı azaltır.': 'The wider family is an important source of support; shared rules reduce conflict.',
  'Geniş bir tavada 1 yemek kaşığı zeytinyağını yüksek ateşte ısıtın; tavukları ekleyip suyunu salıp tekrar çekene ve hafif kızarana kadar 6–7 dakika soteleyin, tabağa alın.': 'Heat 1 tablespoon of olive oil in a wide pan over high heat; sauté the chicken for 6–7 minutes until it releases and reabsorbs its juices and browns lightly, then transfer to a plate.',
  'Geniş bir tavada zeytinyağı ve tereyağını ısıtın; sarımsağı 30 saniye kavurun.': 'Heat the olive oil and butter in a large pan; fry the garlic for 30 seconds.',
  'Geniş bir tavada zeytinyağını orta-yüksek ateşte ısıtın; filetoları tek kat hâlinde dizip her yüzünü 2–3 dakika altın rengi olana kadar pişirin ve tabağa alın.': 'Heat the olive oil in a wide pan over medium-high heat; arrange the fillets in one layer and cook each side for 2–3 minutes until golden, then transfer to a plate.',
  'Geniş tava veya wokta yağı çok yüksek ateşte ısıtın; tavukları 5 dakika sürekli çevirerek pişirin, tabağa alın.': 'Heat the oil in a wide pan or wok over very high heat; cook the chicken for 5 minutes, stirring constantly, and transfer to a plate.',
  'Geniş tavada zeytinyağını yüksek ateşte ısıtın, mantarları 5 dakika suyunu çekene kadar soteleyin.': 'Heat the olive oil in a wide pan over high heat and sauté the mushrooms for 5 minutes until the liquid evaporates.',
  'Geniş tavada zeytinyağını ısıtıp butları her iki yüzü altın rengi olana kadar toplam 8 dakika pişirin, tabağa alın.': 'Heat the olive oil in a wide pan and cook the thighs for a total of 8 minutes until golden on both sides, then transfer to a plate.',
