  'Göz çapağını kaynatılıp soğutulmuş suya batırılmış temiz pamukla içten dışa sil.': 'Wipe sticky eyes from the inside out with clean cotton wool dipped in boiled and cooled water.',
  'Göz, göz bebeği': 'Eye, apple of the eye',
  'Gözde kızarıklık ve yoğun sarı-yeşil çapak; yenidoğanda her zaman değerlendirilmeli.': 'Red eye with thick yellow-green discharge; in a newborn it always needs to be checked.',
  'Göze veya cilde temas ettiyse bol suyla en az 15 dakika yıka.': 'If it got in the eyes or on the skin, rinse with plenty of water for at least 15 minutes.',
