  'Günlük bakımda geniş spektrumlu SPF 30 veya üzeri güneş koruyucu kullanın. Açık havada ürünün etiketine göre yenileyin; gölge ve şapka gibi fiziksel önlemleri ekleyin.': 'Use a broad-spectrum SPF 30 or higher sunscreen in your daily routine. Reapply outdoors according to the label; add physical measures such as shade and a hat.',
