  'Günlük hareket, iletişim ve oyun gözlemlerinizi kaydedin. Gelişim hızı çocuklar arasında değişebilir.': 'Record your daily movement, communication and play observations. Development pace varies between children.',
  'Günlük hareketliliğe uygun kumaş ve kalıpları seçin. Mevsim ve gün içindeki sıcaklık değişimine göre katmanlı giyinin.': 'Choose fabrics and cuts suited to daily activity. Dress in layers according to the season and temperature changes through the day.',
