  'Hazır olma belirtileri varsa ek gıdaya başla: tek tek, birkaç gün arayla, püre kıvamında. Demirden zengin besinler (et, yumurta sarısı, mercimek) öncelikli. Tuz, şeker ve bal eklenmez; anne sütü devam eder.': 'If there are signs of readiness, start solid foods: one at a time, a few days apart, as purées. Iron-rich foods (meat, egg yolk, lentils) come first. No salt, sugar or honey is added; breastfeeding continues.',
