  'Yenidoğan yoğun bakımda ten tene temas (kanguru bakımı) mümkünse uygula.': 'Do skin-to-skin contact (kangaroo care) in the neonatal unit if possible.',
  'Yenidoğan yüzleri 20–30 cm mesafeden en iyi görür, annesinin sesini ve kokusunu tanır. Emme, yakalama ve irkilme refleksleri vardır.': 'Newborns see faces best from 20–30 cm away and recognise their mother\'s voice and smell. They have sucking, grasping and startle reflexes.',
  'Yenidoğanda gözyaşı kanalı tıkanıklığı sulanma ve hafif çapaklanmaya neden olabilir.': 'A blocked tear duct in newborns can cause watering and mild stickiness.',
