  'Yumurtlama ve verimli dönem, ortalama döngü süresine göre yaklaşık hesaplanır. Doğum kontrolü veya gebelik planlaması için güvenilir bir yöntem değildir; tıbbi değerlendirme yerine geçmez.': 'Ovulation and the fertile window are estimated from your average cycle length. This is not a reliable method for contraception or pregnancy planning, and it does not replace medical evaluation.',
  'Yumurtlama çoğunlukla bir sonraki adetten yaklaşık 14 gün önce olur.': 'Ovulation usually happens about 14 days before the next period.',
  'Yumurtlama çoğunlukla bu haftanın sonuna doğru olur; döllenme yumurtlamadan sonraki yaklaşık bir gün içinde gerçekleşebilir.': 'Ovulation usually happens towards the end of this week; fertilisation can occur within about a day after ovulation.',
