  'Yüz temizliği, nemlendirme ve güneşten korunmayı üç kısa adıma bölün. Yeni ürünleri tek tek ekleyerek cildinizin tepkisini gözlemleyin.': 'Split face cleansing, moisturising and sun protection into three short steps. Add new products one at a time and watch how your skin reacts.',
