  'İlk 6 ay bebeğin ebeveynlerle aynı odada, ama kendi yatağında uyuması önerilir.': 'For the first 6 months, babies should sleep in the same room as their parents but in their own bed.',
  'İlk 6 ay yalnızca anne sütü önerilir; su, şekerli su veya bitki çayı gerekmez. Anne sütü yeterli değilse mama ihtiyacını çocuk doktoruyla değerlendir. Bebek açlık işareti verdikçe besle (günde 8–12 kez).': 'Exclusive breast milk is recommended for the first 6 months; water, sugar water or herbal tea are not needed. If breast milk isn\'t enough, discuss formula with your paediatrician. Feed whenever your baby shows hunger cues (8–12 times a day).',
